package org.jlinalg.cli;
import java.io.IOException;
import java.nio.file.Path;
import java.util.*;
import org.jlinalg.omics.contact.HicProContactAudit;
import static org.jlinalg.cli.NextflowFiles.*;

/** Explicit complete paired-end cohort and original restriction-digestion Hi-C parameters. */
final class NfcoreHic210Request {
    private NfcoreHic210Request(){ }
    record Library(String first,String second) { }
    record Sample(String id,List<Library> libraries){Sample{libraries=List.copyOf(libraries);}}
    record Request(String source,String containerHome,String imageSet,String fasta,String assemblyLabel,List<Sample> samples,Map<String,Object> science,int executorCpus,long executorMemory,int taskCpus,long taskMemory,long taskSeconds,long maximumReads,HicProContactAudit.Limits auditLimits,Map<?,?> limits,Map<?,?> raw){Request{samples=List.copyOf(samples);science=Map.copyOf(science);}}
    static Request read(Path p)throws IOException{return parse(object(NextflowParameters.parse(utf8(bytes(p,4194304)),4194304,100000)));}
    static Request parse(Map<?,?> raw)throws IOException{
        keys(raw,"schema_version","pipeline_profile","engine_profile","source_directory","container_home","image_set","fasta","reference_assembly_label","samples","science","executor_cpus","executor_memory_bytes","task_cpus","task_memory_bytes","task_seconds","maximum_reads_per_sample","maximum_pairs","maximum_bins","maximum_pixels","maximum_line_characters","maximum_decoded_characters","limits");integer(raw.get("schema_version"),1,1);
        if(!NfcoreHic210Profile.ID.equals(raw.get("pipeline_profile"))||!NfcoreHic210Profile.ENGINE.equals(raw.get("engine_profile")))throw new NextflowProcess.Unavailable("Require explicit original HiC2.1.0 and selected qualified Nextflow22.10.6; another or unreported edition is not substituted");
        int executorCpus=(int)integer(raw.get("executor_cpus"),1,1024),taskCpus=(int)integer(raw.get("task_cpus"),1,1024);long executorMemory=integer(raw.get("executor_memory_bytes"),16777216,1099511627776L),taskMemory=integer(raw.get("task_memory_bytes"),16777216,1099511627776L);if(taskCpus>executorCpus||taskMemory>executorMemory)throw new IOException("Declared original task maxima exceed executor capacity");
        var samples=new ArrayList<Sample>();var ids=new HashSet<String>();int libraries=0;
        for(Object item:list(raw.get("samples"))){var row=object(item);keys(row,"id","libraries");String id=token(text(row.get("id")),"sample ID");if(!ids.add(id))throw new IOException("Repeated sample object; retain its complete technical-library population under one sample");var runs=new ArrayList<Library>();var firsts=new HashSet<String>();
            for(Object item2:list(row.get("libraries"))){var r=object(item2);keys(r,"fastq_1","fastq_2");String first=path(r.get("fastq_1")),second=text(r.get("fastq_2"));if(second.isEmpty())throw new NextflowProcess.Unavailable("Original Hi-C mapping requires both read mates; single-end input cannot be substituted");second=path(second);String a=fastq(first),b=fastq(second);if(!a.equals(b))throw new IOException("Original mate suffixes differ; no rename/compression is inferred");if(first.equals(second)||!firsts.add(first))throw new IOException("Repeated source sample/first-FASTQ pair or identical mate paths");runs.add(new Library(first,second));if(++libraries>100000)throw new IOException("Complete technical-library capacity exceeded");}
            if(runs.isEmpty())throw new IOException("Sample has no declared technical libraries");samples.add(new Sample(id,runs));
        }
        if(samples.isEmpty())throw new IOException("Declare the entire nonempty cohort");
        Map<?,?> supplied=object(raw.get("science"));keys(supplied,"digestion","min_mapq","min_restriction_fragment_size","max_restriction_fragment_size","min_insert_size","max_insert_size","min_cis_dist","keep_dups","keep_multi","bin_size","res_zoomify","res_dist_decay","res_tads","res_compartments","tads_caller","hicpro_maps","ice_max_iter","ice_filter_low_count_perc","ice_filter_high_count_perc","ice_eps");var science=new LinkedHashMap<String,Object>();String digestion=text(supplied.get("digestion"));if(!Set.of("hindiii","mboi","dpnii","arima").contains(digestion))throw new NextflowProcess.Unavailable("Select an original named restriction protocol. DNase/custom motifs require their separate source-output contracts; no digestion substitution is inferred");science.put("digestion",digestion);
        for(String name:List.of("min_mapq","min_restriction_fragment_size","max_restriction_fragment_size","min_insert_size","max_insert_size","min_cis_dist"))science.put(name,integer(supplied.get(name),0,name.equals("min_mapq")?255:Integer.MAX_VALUE));
        for(String name:List.of("keep_dups","keep_multi","hicpro_maps")){if(!(supplied.get(name)instanceof Boolean flag))throw new IOException("Declare explicit source boolean: "+name);science.put(name,flag);}
        for(String name:List.of("bin_size","res_dist_decay","res_tads","res_compartments"))science.put(name,resolutions(text(supplied.get(name)),false));science.put("res_zoomify",resolutions(text(supplied.get("res_zoomify")),true));
        String caller=text(supplied.get("tads_caller"));if(!Set.of("insulation","hicexplorer","insulation,hicexplorer","hicexplorer,insulation").contains(caller))throw new IOException("Declare the original TAD caller selection explicitly");science.put("tads_caller",caller);science.put("ice_max_iter",integer(supplied.get("ice_max_iter"),1,Integer.MAX_VALUE));
        for(String name:List.of("ice_filter_low_count_perc","ice_filter_high_count_perc","ice_eps")){Object value=supplied.get(name);double numeric;
            try{String literal=value instanceof NextflowParameters.NumberToken token?token.text():value instanceof Number?value.toString():"";var decimal=new java.math.BigDecimal(literal);numeric=decimal.doubleValue();if(!Double.isFinite(numeric)||decimal.signum()<0||name.endsWith("perc")&&decimal.compareTo(java.math.BigDecimal.ONE)>0||name.equals("ice_eps")&&numeric==0)throw new NumberFormatException("outside original numeric domain");}
            catch(NumberFormatException invalid){throw new IOException("Invalid original ICE numeric parameter: "+name,invalid);}science.put(name,value);}
        String fasta=path(raw.get("fasta"));token(fasta.substring(fasta.lastIndexOf('/')+1),"FASTA basename");String label=text(raw.get("reference_assembly_label"));if(label.isEmpty()||label.length()>1024||label.chars().anyMatch(c->c<32||c==127))throw new IOException("Declare the literal reference provenance label; it never certifies assembly identity");
        var capacity=new HicProContactAudit.Limits(integer(raw.get("maximum_pairs"),1,1000000000),(int)integer(raw.get("maximum_bins"),1,Integer.MAX_VALUE),(int)integer(raw.get("maximum_pixels"),1,Integer.MAX_VALUE),(int)integer(raw.get("maximum_line_characters"),128,16000000),integer(raw.get("maximum_decoded_characters"),1,2000000000000L));
        return new Request(path(raw.get("source_directory")),path(raw.get("container_home")),path(raw.get("image_set")),fasta,label,samples,science,executorCpus,executorMemory,taskCpus,taskMemory,integer(raw.get("task_seconds"),1,604800),integer(raw.get("maximum_reads_per_sample"),1,1000000000),capacity,object(raw.get("limits")),raw);
    }
    static String path(Object raw)throws IOException{return NfcoreRnasplice104Request.path(raw);}
    static String token(String s,String field)throws IOException{if(s.isEmpty()||s.equals(".")||s.equals(".."))throw new IOException("Empty/dot literal "+field);if(s.codePoints().anyMatch(c->!Character.isLetterOrDigit(c)&&"_.-+:=@%".indexOf(c)<0))throw new NextflowProcess.Unavailable("The original shell/path interpolation cannot safely represent this unchanged "+field+". Analysis skipped; no identifier/filename repair is inferred: "+s);return s;}
    private static String fastq(String path)throws IOException{String n=path.substring(path.lastIndexOf('/')+1);token(n,"FASTQ basename");if(n.endsWith(".fastq.gz"))return".fastq.gz";if(n.endsWith(".fq.gz"))return".fq.gz";throw new IOException("Original checker requires .fastq.gz/.fq.gz; no compression or rename is inferred");}
    static String resolutions(String s,boolean empty)throws IOException{if(s.isEmpty()&&empty)return s;var seen=new HashSet<String>();for(String token:s.split(",",-1))if(!token.matches("[1-9][0-9]*")||token.length()>10||Long.parseLong(token)>Integer.MAX_VALUE||!seen.add(token))throw new IOException("Require explicit distinct positive source resolutions, without whitespace or repair");return s;}
    static List<Long> mapResolutions(Request r){var result=new LinkedHashSet<Long>();for(String name:List.of("bin_size","res_zoomify","res_tads","res_dist_decay","res_compartments"))for(String value:r.science().get(name).toString().split(","))if(!value.isEmpty())result.add(Long.parseLong(value));return List.copyOf(result);}
}
